import { z } from "zod";
import type { SupabaseClient } from "@supabase/supabase-js";
import { GatewayError, type Gateway } from "../ai/gateway.ts";
import type { LabExtractOutput } from "../ai/skills/labs.ts";
import type { Database, Json } from "../db/types.ts";
import { publicExperiment, type ExperimentConfig } from "../labs/experiment.ts";
import { verifyExperiment } from "../labs/verify.ts";
import { mergeChunks } from "./exam-extract.ts";
import { JobFailure, type JobHandler } from "./types.ts";

// lab_extract (04 §4.8, 05 §9, 10 MVP-05): a lab manual's text, or a practical the student asked
// for, → experiment configurations → the experiment verifier → saved labs, or declined with a
// reason. Nothing unverified is ever saved as a runnable lab (guardrails 2–3).
//
// Topic labs are shared and cached by topic (12 §4 Q55): a second student asking for the same
// practical gets the existing lab with no AI call. Manual labs belong to the manual's owner.

export const labExtractPayload = z.discriminatedUnion("mode", [
  z.object({
    mode: z.literal("manual"),
    user_id: z.string().uuid(),
    source_id: z.string().uuid(),
    course_id: z.string().uuid().nullable(),
  }),
  z.object({
    mode: z.literal("topic"),
    user_id: z.string().uuid(),
    topic: z.string().trim().min(2).max(200),
    course_id: z.string().uuid().nullable(),
  }),
]);
export type LabExtractPayload = z.infer<typeof labExtractPayload>;

const MAX_TEXT = 40_000;
const MSG = {
  failed: "Ifiok couldn't build a lab from this. Try again, or name the practical another way.",
  notManual: "Only your own lab manuals can become labs.",
} as const;

/** "Hooke's Law " → "hookes law": one cached shared lab per practical however it's typed. */
export function topicKey(topic: string): string {
  return topic
    .toLowerCase()
    .replace(/['’`]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
    .replace(/^(the|a|an) /, "");
}

export type SavedLab = { id: string; title: string; status: "ready" | "declined"; reason: string | null };

export type NewLab = {
  ownerId: string | null;
  origin: "manual" | "topic";
  topicKey: string | null;
  sourceId: string | null;
  title: string;
  subject: string | null;
  createdBy: string;
} & (
  | { status: "ready"; config: ExperimentConfig; publicConfig: Json; hash: string }
  | { status: "declined"; reason: string }
);

export type LabRepo = {
  source(id: string): Promise<{ ownerId: string; kind: string; courseId: string | null; title: string } | null>;
  chunks(sourceId: string): Promise<{ page: number | null; content: string }[]>;
  course(id: string): Promise<{ subject: string | null; level: number | null } | null>;
  /** The member check for a course the lab is filed under. */
  isMember(userId: string, courseId: string): Promise<boolean>;
  sharedByTopic(key: string): Promise<SavedLab | null>;
  /** Removes earlier labs built from this manual, so a retried job doesn't duplicate them. */
  clearSource(sourceId: string): Promise<void>;
  /** Saves a lab; a shared topic lab that already exists is returned instead. */
  save(lab: NewLab): Promise<SavedLab>;
  link(userId: string, labId: string, courseId: string | null): Promise<void>;
};

async function sha256(text: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, "0")).join("");
}

export function createSupabaseLabRepo(db: SupabaseClient<Database>): LabRepo {
  const asSaved = (r: { id: string; title: string; status: string; decline_reason: string | null }): SavedLab => ({
    id: r.id,
    title: r.title,
    status: r.status === "ready" ? "ready" : "declined",
    reason: r.decline_reason,
  });
  return {
    async source(id) {
      const { data } = await db.from("sources").select("owner_id, kind, course_id, title").eq("id", id).maybeSingle();
      return data ? { ownerId: data.owner_id, kind: data.kind, courseId: data.course_id, title: data.title } : null;
    },
    async chunks(id) {
      const { data, error } = await db.from("chunks").select("page, content").eq("source_id", id).order("id");
      if (error) throw new Error("Couldn't load the manual");
      return data ?? [];
    },
    async course(id) {
      const { data } = await db.from("courses").select("subject, level").eq("id", id).maybeSingle();
      return data;
    },
    async isMember(userId, courseId) {
      const { count } = await db
        .from("enrollments")
        .select("user_id", { count: "exact", head: true })
        .eq("user_id", userId)
        .eq("course_id", courseId);
      return (count ?? 0) > 0;
    },
    async sharedByTopic(key) {
      const { data } = await db
        .from("labs")
        .select("id, title, status, decline_reason")
        .is("owner_id", null)
        .eq("origin", "topic")
        .eq("topic_key", key)
        .maybeSingle();
      return data ? asSaved(data) : null;
    },
    async clearSource(sourceId) {
      const { error } = await db.from("labs").delete().eq("source_id", sourceId);
      if (error) throw new Error("Couldn't clear earlier labs");
    },
    async save(lab) {
      const row = {
        owner_id: lab.ownerId,
        origin: lab.origin,
        topic_key: lab.topicKey,
        source_id: lab.sourceId,
        title: lab.title,
        subject: lab.subject,
        status: lab.status,
        decline_reason: lab.status === "declined" ? lab.reason : null,
        config: lab.status === "ready" ? (lab.config as unknown as Json) : null,
        public_config: lab.status === "ready" ? lab.publicConfig : null,
        config_hash: lab.status === "ready" ? lab.hash : null,
        created_by: lab.createdBy,
      };
      const { data, error } = await db.from("labs").insert(row).select("id, title, status, decline_reason").single();
      if (!error && data) return asSaved(data);
      // Another student's request for the same practical won the race: use theirs.
      if (lab.ownerId === null && lab.topicKey) {
        const existing = await this.sharedByTopic(lab.topicKey);
        if (existing) return existing;
      }
      throw new Error("Couldn't save the lab");
    },
    async link(userId, labId, courseId) {
      const { error } = await db.from("user_labs").insert({ user_id: userId, lab_id: labId, course_id: courseId });
      // 23505: already in their list.
      if (error && error.code !== "23505") throw new Error("Couldn't add the lab to the list");
    },
  };
}

export type LabExtractDeps = { repo: LabRepo; gateway: Pick<Gateway, "run"> };

export function createLabExtractHandler(deps: LabExtractDeps): JobHandler {
  const { repo } = deps;

  /** The primary model, then the backup provider (04 §3); an exhausted allowance ends the job. */
  const extract = async (userId: string, input: unknown): Promise<LabExtractOutput> => {
    try {
      return (await deps.gateway.run<LabExtractOutput>("lab_extract", { userId, mode: "job", attempt: 1, input }))
        .output;
    } catch (err) {
      if (err instanceof GatewayError && (err.code === "quota_exhausted" || err.code === "not_allowed"))
        throw new JobFailure(err.code, err.message, false);
      try {
        return (await deps.gateway.run<LabExtractOutput>("lab_extract", { userId, mode: "job", attempt: 2, input }))
          .output;
      } catch (again) {
        if (again instanceof GatewayError)
          throw new JobFailure(again.code, again.message, again.code !== "quota_exhausted");
        throw again;
      }
    }
  };

  /** Verifies each configuration; returns the ready ones and the reasons the rest were declined. */
  const judge = async (out: LabExtractOutput, source: "manual" | "topic") => {
    const ready: { config: ExperimentConfig; publicConfig: Json; hash: string }[] = [];
    const declined: { title: string; reason: string }[] = [...out.declined];
    for (const raw of out.experiments) {
      const verdict = verifyExperiment({ ...raw, source });
      const title = typeof raw.title === "string" && raw.title.trim() ? raw.title.trim().slice(0, 120) : "Practical";
      if (!verdict.ok) {
        declined.push({ title, reason: verdict.reason });
        continue;
      }
      const config = verdict.compiled.config;
      ready.push({
        config,
        publicConfig: publicExperiment(verdict.compiled) as unknown as Json,
        hash: await sha256(JSON.stringify(config)),
      });
    }
    return { ready, declined };
  };

  return {
    async run(job) {
      const parsed = labExtractPayload.safeParse(job.payload);
      if (!parsed.success || parsed.data.user_id !== job.ownerId)
        throw new JobFailure("bad_payload", MSG.failed, false);
      const p = parsed.data;
      // Guardrail 7: a course in the payload is one the student belongs to.
      if (p.course_id && !(await repo.isMember(p.user_id, p.course_id)))
        throw new JobFailure("not_a_member", MSG.failed, false);
      const course = p.course_id ? await repo.course(p.course_id) : null;
      const subject = course?.subject ?? null;
      const level = course?.level ? `${course.level} level` : null;

      if (p.mode === "topic") {
        const key = topicKey(p.topic);
        if (!key) throw new JobFailure("empty_topic", MSG.failed, false);
        // Cached: someone already built this practical. No AI call.
        const cached = await repo.sharedByTopic(key);
        if (cached?.status === "ready") {
          await repo.link(p.user_id, cached.id, p.course_id);
          return { kind: "done", result: { labs: [cached], declined: [] } as unknown as Json };
        }
        const out = await extract(p.user_id, { manual: null, topic: p.topic, subject, level });
        const { ready, declined } = await judge(out, "topic");
        const first = ready[0];
        if (!first) {
          // Not cached: a decline might be the model's mistake, and asking again may work.
          const reason = declined[0]?.reason ?? "It isn't a measure-and-analyse practical.";
          return { kind: "done", result: { labs: [], declined: [{ title: p.topic, reason }] } as unknown as Json };
        }
        const saved = await repo.save({
          ownerId: null,
          origin: "topic",
          topicKey: key,
          sourceId: null,
          title: first.config.title,
          subject,
          createdBy: p.user_id,
          status: "ready",
          ...first,
        });
        await repo.link(p.user_id, saved.id, p.course_id);
        return { kind: "done", result: { labs: [saved], declined: [] } as unknown as Json };
      }

      // A manual: the job owner's own lab manual, filed under the course in the payload (if any).
      const source = await repo.source(p.source_id);
      if (!source || source.ownerId !== p.user_id) throw new JobFailure("payload_owner_mismatch", MSG.notManual, false);
      if (source.kind !== "lab_manual" || (p.course_id && source.courseId !== p.course_id))
        throw new JobFailure("not_a_manual", MSG.notManual, false);
      const chunks = await repo.chunks(p.source_id);
      if (!chunks.length) throw new JobFailure("nothing_to_read", MSG.failed, false);
      const out = await extract(p.user_id, {
        manual: mergeChunks(chunks).slice(0, MAX_TEXT),
        topic: null,
        subject,
        level,
      });
      const { ready, declined } = await judge(out, "manual");

      await repo.clearSource(p.source_id);
      const base = {
        ownerId: p.user_id,
        origin: "manual" as const,
        topicKey: null,
        sourceId: p.source_id,
        subject,
        createdBy: p.user_id,
      };
      const labs: SavedLab[] = [];
      for (const r of ready) labs.push(await repo.save({ ...base, title: r.config.title, status: "ready", ...r }));
      // Declined practicals are kept so the student sees why ("not available as a virtual lab").
      for (const d of declined.slice(0, 5))
        labs.push(await repo.save({ ...base, title: d.title, status: "declined", reason: d.reason }));
      for (const lab of labs) await repo.link(p.user_id, lab.id, p.course_id);
      return {
        kind: "done",
        result: {
          labs: labs.filter((l) => l.status === "ready"),
          declined: labs.filter((l) => l.status === "declined"),
        } as unknown as Json,
      };
    },
  };
}
